const t={ui:{fig:"Abb. 1",title:"Utensilo · Anatomie",svgLabel:"Eine isometrische Zeichnung des gefütterten Utensilos aus Stoff und wie es Schritt für Schritt genäht wird.",prev:"Vorheriger Schritt",dot:(e,n)=>e?`Schritt ${e}: ${n}`:n,start:"Schritte →",next:"Weiter →",overview:"Übersicht",stepOf:(e,n)=>`Schritt ${e} von ${n}`,machine:e=>`Maschine: ${e}`,inThisStep:"In diesem Schritt",takeApart:"Zerlegen",putTogether:"Zusammensetzen",replay:"↻ Noch einmal",parts:"Teile",allSteps:"Schritt-für-Schritt-Anleitung",endView:"QUERSCHNITT",cutTitle:"Utensilo mit Futter · Zuschnittmaße",cutAlt:"Zuschnittplan für ein Utensilo aus Stoff mit Futter: Außenteil und Futter je ein Quadrat von 60 × 60 cm, aus dem an jeder Ecke ein Quadrat von 20 × 20 cm ausgeschnitten wird, dazu fünf Quadrate Bügeleinlage, 19 × 19 cm.",cutCaption:"Alle Zuschnitte mit ihren Maßen – wie in Schritt 1."},stitches:{straight:"Geradstich"},labels:{cm60:"60 cm",cm20:"20 cm",cm19:"19 cm",cutCorners:"Ecken ausschneiden",outerCotton:"außen · Baumwolle",liningCotton:"Futter · Baumwolle",iface5:"5 × Bügeleinlage",wrongSideUp:"Außenteil, linke Seite oben",ironOn:"aufbügeln",edges05:"0,5 cm vom Rand",turnOver:"umdrehen",rightSideIn:"rechte Seite innen",seam05:"Naht 0,5 cm",toThePoint:"bis zur Spitze",opening15:"Öffnung 15 cm",sameAsOuter:"wie das Außenteil",outerRightOut:"Außenteil auf rechts",rightSides:"rechts auf rechts",turnThrough:"durch die Öffnung wenden",stitchClosed:"zunähen",pushLining:"Futter hineinschieben",topstitch05:"0,5 cm absteppen",hotGlue:"Heißkleber statt Nähen",jointFlat:"Ansatzstelle auf einer Wand",bows4:"eine Schleife pro Ecke",christmas:"Weihnachten: Spitze, Schleifen",halloween:"Halloween: schwarzes Band",everyday:"Alltag: ohne Deko"},steps:[{title:"Das fertige Utensilo",text:"Ein gefüttertes Utensilo aus Stoff: ein Außenteil aus Baumwolle, mit Bügeleinlage verstärkt, ein Futter aus Baumwolle und dazu aufgeklebte Spitze und Schleifen. Tippe auf das Utensilo, um es zu zerlegen."},{title:"Zuschneiden",text:"Außenteil und Futter: je ein Quadrat Baumwolle von 60 × 60 cm, aus dem an jeder Ecke ein Quadrat von 20 × 20 cm ausgeschnitten wird. Bügeleinlage: fünf Quadrate von 19 × 19 cm.",details:["Schneide aus Baumwolle ein Quadrat von 60 × 60 cm für das Außenteil zu und ein zweites für das Futter.","Schneide an jeder Ecke beider Quadrate ein Quadrat von 20 × 20 cm heraus. Übrig bleibt ein Kreuz: Das Quadrat in der Mitte ist der Boden, die vier Arme sind die Wände.","Schneide aus fester Bügeleinlage fünf Quadrate von 19 × 19 cm zu: eines für den Boden und je eines für jede Wand des Außenteils.","Die Nahtzugabe beträgt bei diesem Utensilo überall 0,5 cm.","Im Video ist 50 × 50 cm eingeblendet – das ist ein Fehler: Die Quadrate sind 60 × 60 cm groß."]},{title:"Bügeleinlage aufbügeln",text:"Leg das Außenteil mit der linken Seite nach oben hin. Leg je ein Quadrat Bügeleinlage mittig auf den Boden und auf jede Wand, 0,5 cm von den Kanten entfernt, und bügle sie auf.",details:["Leg das Kreuz des Außenteils mit der linken Seite nach oben hin.","Leg mittig auf den Boden und auf jede der vier Wände ein Quadrat Bügeleinlage, die Klebeseite nach unten – rundherum 0,5 cm von den Kanten entfernt, damit sie nicht in die Nähte gerät.","Bügle die Quadrate auf. Die Bügeleinlage kommt nur aufs Außenteil, nicht aufs Futter."]},{title:"Außenteil nähen",text:"Dreh das Außenteil um, rechte Seite nach oben, und klappe die Wände hoch. Stecke die Kanten, die aufeinandertreffen, fest und nähe die vier Ecknähte mit 0,5 cm Nahtzugabe – von oben bis hinunter zur Spitze.",details:["Dreh das Kreuz des Außenteils um, sodass die rechte Seite oben liegt.","Klappe die Wände hoch, sodass die Kanten zweier benachbarter Wände rechts auf rechts aufeinandertreffen. Stecke sie fest.","Nähe die Ecknaht 0,5 cm von der Kante entfernt, von der Oberkante bis ganz hinunter zur Spitze am Boden. Nicht verriegeln.","Nähe so alle vier Ecken. Das Außenteil ist jetzt eine Box, auf links gedreht – die Bügeleinlage liegt außen."]},{title:"Futter nähen",text:"Nähe das Futter genauso, ohne Bügeleinlage – lass aber in einer Ecknaht eine 15 cm lange Wendeöffnung. Durch sie wendest du später das Utensilo.",details:["Klappe die Wände des Futterkreuzes hoch, rechts auf rechts, und stecke die Kanten, die aufeinandertreffen, fest.","Nähe drei Ecknähte 0,5 cm von der Kante entfernt, von oben bis zur Spitze.","Nähe auch die vierte, lass darin aber eine 15 cm lange Wendeöffnung. Sie ist so groß, weil die Wände des Außenteils mit der Bügeleinlage steif sind und Platz zum Durchziehen brauchen.","Lass das Futter auf links."]},{title:"Außenteil und Futter verbinden",text:"Wende das Außenteil auf rechts und schieb es in das auf links gedrehte Futter, rechts auf rechts. Nähe rundherum an der Oberkante entlang, 0,5 cm von der Kante entfernt.",details:["Wende das Außenteil auf rechts.","Schieb es in das Futter, das auf links bleibt, sodass die rechten Seiten aufeinanderliegen. Leg die Ecknähte und die Oberkanten genau aufeinander.","Nähe einmal rundherum an der Oberkante entlang, 0,5 cm von der Kante entfernt."]},{title:"Wenden",text:"Wende das Utensilo durch die Öffnung im Futter auf rechts und nähe die Öffnung dann mit der Maschine zu.",details:["Zieh das ganze Utensilo durch die 15 cm lange Öffnung im Futter.","Schlag die offenen Kanten der Öffnung nach innen ein und nähe sie mit der Maschine knappkantig zu."]},{title:"Oberkante absteppen",text:"Schieb das Futter nach unten ins Utensilo und steppe die Oberkante rundherum 0,5 cm von der Kante entfernt ab.",details:["Schieb das Futter nach unten ins Utensilo hinein, bis ganz in die Ecken.","Steppe rundherum an der Oberkante ab, 0,5 cm von der Kante entfernt. Das Utensilo ist fertig – wie du es verzierst, liegt ganz bei dir."]},{title:"Verzieren",text:"Klebe mit Heißkleber ein Band rund um die Oberkante, die Ansatzstelle auf einer flachen Wand, und auf jede Ecke eine Schleife. Jedes Band und jede Schleife passen – oder du lässt die Deko ganz weg.",details:["Die Deko wird mit der Heißklebepistole aufgeklebt, nicht angenäht.","Klebe ein Band einmal rundherum an der Oberkante fest. Leg die Ansatzstelle auf die Fläche einer Wand, nicht an eine Ecke.","Klebe auf jede der vier Ecken eine Schleife. Im Video sind sie vorher aus weißem Band gebunden, in der Mitte ist eine rote Halbperle aus Kunststoff aufgeklebt – gekaufte Schleifen gehen genauso gut.","Jedes Band in jeder Breite: Spitze für Weihnachten wie im Video, ein schlichtes schwarzes Band oder ein orangefarbenes mit Kürbissen für Halloween – oder für jeden Tag gar keine Deko. Im Video liegen in dem Utensilo Mandarinen für den Weihnachtstisch – du kannst deines für alles nutzen, was du magst."]}],legend:[{title:"Außenteil",text:"Baumwolle · Quadrat 60 × 60 cm, an jeder Ecke ein Quadrat von 20 × 20 cm ausgeschnitten"},{title:"Bügeleinlage ×5",text:"fest, zum Aufbügeln · Quadrate 19 × 19 cm auf Boden und Wänden des Außenteils, 0,5 cm von den Kanten entfernt"},{title:"Futter",text:"Baumwolle · dasselbe Kreuz wie das Außenteil, ohne Bügeleinlage"},{title:"Band",text:"Spitze oder ein beliebiges Band · mit Heißkleber rund um die Oberkante geklebt, die Ansatzstelle auf einer flachen Wand"},{title:"Schleifen ×4",text:"eine auf jeder Ecke, aufgeklebt, in der Mitte eine rote Halbperle"},{title:"Nähte",text:"alle 0,5 cm · eine 15 cm lange Öffnung in einer Ecknaht des Futters · Steppnaht 0,5 cm von der Oberkante"}]};export{t as default};
